head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vcontnId = "";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_Top);
        await scwin.setInit();
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF60011.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF60011.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF60011.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description grd_Grid 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    try {
        if (colid === 'TITLE') {
            scwin.setContnId(dts_List.getCellData(row, "CONTN_ID"));
            let wth = 790;
            let hgt = 580;
            let pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
            await $c.frame.CreateDialogFrame("gform", "/lstmgt/ULDSTF60012.gfm?frameID=" + frame.FrameID, "심사관련 이슈사항 수정", pt.x, pt.y, wth, hgt, "window");
            await scwin.listSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF60011.grd_Grid_OnDblClick" });
    }
};

/**
 * @method
 * @name edt_KeyWord_onkeydown
 * @description edt_KeyWord 키 입력 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.edt_KeyWord_onkeydown = async function() {
    try {
        if (window.event.keyCode === 13) {
            await scwin.listSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF60011.edt_KeyWord_onkeydown" });
    }
};

/**
 * @method
 * @name cmb_PeriodTp_onselchange
 * @description cmb_PeriodTp onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PeriodTp_onselchange = function() {
    try {
        const vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
        if (vTp === '*') {
            edt_SDate.setValue("20200101");
            edt_EDate.setValue($c.ut.cGetToday("yyyymmdd"));
        } else $c.stf.setFromToDate(vTp, edt_SDate, edt_EDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF60011.cmb_PeriodTp_onselchange" });
    }
};

/**
 * @method
 * @name icn_ECal_onclick
 * @description icn_ECal 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.icn_ECal_onclick = function() {
    try {
        popUpCalendar2(edt_EDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF60011.icn_ECal_onclick" });
    }
};

/**
 * @method
 * @name icn_SCal_onclick
 * @description icn_SCal 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.icn_SCal_onclick = function() {
    try {
        popUpCalendar2(edt_SDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF60011.icn_SCal_onclick" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF60011.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave("ULDSTF60011.xml", SCREN_PROCS_TP_CD_07, '');
        $c.data.downloadGridViewExcel(grd_Grid, {fileName: "심사관련주요이슈사항", type: "2"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF60011.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name btn_Input_onclick
 * @description 「입력」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Input_onclick = async function() {
    try {
        let wth = 790;
        let hgt = 580;
        let pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
        scwin.setContnId("input");
        const options = {
            id: "ULDSTF60012",
            title: "심사관련 이슈사항 등록",
            type: "browserPopup",
            width: wth,
            height: hgt,
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("/lstmgt/ULDSTF60012.gfm", options);
        scwin.vcontnId = "";
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF60011.btn_Input_onclick" });
    }
};

/**
 * @method
 * @name img_keyword_srch_onclick
 * @description img_keyword_srch 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_keyword_srch_onclick = async function() {
    try {
        let wth = 730 + 5;
        let hgt = 785 + 30;
        let pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
        scwin.vcontnId = "search";
        const options = {
            id: "ULDSTF60013",
            title: "주요키워드 선택 ",
            type: "browserPopup",
            width: "920px",
            height: "580px",
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("/lstmgt/ULDSTF60013.gfm", options);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF60011.img_keyword_srch_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setInit
 * @description set Init 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setInit = async function() {
    edt_SDate.setValue("20200101");
    edt_EDate.setValue($c.ut.cGetToday("yyyymmdd"));
    const arrCid = [{
        cid: "LIST_INVSTG_ISUE_TP_CD",
        cnm: "cmb_IsueTp"
    }];
    let objCod;
    url += "&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT";
    url += "&CD_ID_M='LIST_INVSTG_ISUE_TP_CD'";
    const sbmOptions = {
        id : "sbm_dts_Code",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_Code=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    let strCbd = "",
        i, j;
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        if (objCod === null) {
            await $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "A^전체";
        for (j = 1; j <= dts_Code.getRowCount(); j++) {
            if (dts_Code.getCellData(j, "CD_ENG_NM") === arrCid[i].cid) {
                strCbd = strCbd + (strCbd === "" ? "" : ",") + dts_Code.getCellData(j, "VALUE") + "^" + dts_Code.getCellData(j, "TEXT");
            }
        }
        objCod.CBData = strCbd;
    }
    cmb_IsueTp.setSelectedIndex(0);

    //--------------------------------------------------------
    const sbmOptions2 = {
        id : "sbm_dts_issuedtl",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_issuedtl=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // dts_issuedtl.AddRow();

    const sbmOptions3 = {
        id : "sbm_dts_issuedtlyn",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_issuedtlyn=body.content",
        isProcessMsg : false
    };

    const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);
    // TODO Stage2: sbmRtn3 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    if (await scwin.dateCheck() === false) {
        return;
    }
    let vMajKwdCd = '';
    for (let i = 11; i <= 60; i++) {
        if (dts_issuedtlyn.getCellData(1, "LIST_INVSTG_ISUE_KEYWRD_" + i + "_YN") === '1') {
            vMajKwdCd += i + ",";
        }
    }
    vMajKwdCd = vMajKwdCd.replace(/,$/, '');
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setIsuDtl
 * @description set Isu Dtl 처리
 * @param {*} codeIdx codeIdx
 * @returns {void}
 * @hidden N
 */
scwin.setIsuDtl = function(codeIdx) {
    dts_isudtl.addrow();
    const seq = "" + dts_isudtl.getRowCount();
    dts_isudtl.setCellData(seq, "LIST_INVSTG_ISUE_KEYWRD_TP_CD", codeIdx);
    dts_isudtl.setCellData(seq, "LIST_INVSTG_ISUE_KEYWRD_YN", dts_issueyn.getCellData(1, "LIST_INVSTG_ISUE_KEYWRD_" + codeIdx + "_YN"));
    dts_isudtl.setCellData(seq, "LIST_INVSTG_ISUE_KEYWRD", dts_issueyn.getCellData(1, "LIST_INVSTG_ISUE_KEYWRD_" + codeIdx));
};

/**
 * @method
 * @name dateCheck
 * @description date Check 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dateCheck = async function() {
    if (parseInt(edt_SDate.getValue(), '10') > parseInt(edt_EDate.getValue(), '10')) {
        await $c.win.alert("[조회기간 시작일은 종료일보다 작아야 합니다.]다시 입력해주세요");
        return false;
    }
};

/**
 * @method
 * @name setContnId
 * @description set Contn Id 처리
 * @param {String} contnId contnId
 * @returns {void}
 * @hidden N
 */
scwin.setContnId = function(contnId) {
    scwin.vcontnId = contnId;
};

/**
 * @method
 * @name getContnId
 * @description get Contn Id 처리
 * @returns {void}
 * @hidden N
 */
scwin.getContnId = function() {
    return scwin.vcontnId;
};

/**
 * @method
 * @name setPar
 * @description set Par 처리
 * @param {*} param_dts1 param_dts1
 * @param {*} param_dts2 param_dts2
 * @returns {void}
 * @hidden N
 */
scwin.setPar = function(param_dts1, param_dts2) {
    $c.stf.copyDataSet(param_dts1, dts_issuedtlyn);
    $c.stf.copyDataSet(param_dts2, dts_issuedtl);
};

/**
 * @method
 * @name getPar
 * @description Get checkBox DataSet
 * @param {String} param_contnId param_contnId
 * @param {*} param_dts1 param_dts1
 * @param {*} param_dts2 param_dts2
 * @returns {void}
 * @hidden N
 */
scwin.getPar = function(param_contnId, param_dts1, param_dts2) {
    param_contnId = 'search';
    $c.stf.copyDataSet(dts_issuedtl, param_dts1);
    $c.stf.copyDataSet(dts_issuedtlyn, param_dts2);
};
